Set-Content -Path "js/cart.js" -Value "class Cart {
    constructor() {
        this.items = JSON.parse(localStorage.getItem('cart')) || [];
        this.updateCartCount();
    }

    addItem(product, quantity = 1) {
        const existingItem = this.items.find(item => item.id === product.id);
        if (existingItem) {
            existingItem.quantity += quantity;
        } else {
            this.items.push({ ...product, quantity });
        }
        this.save();
    }

    removeItem(productId) {
        this.items = this.items.filter(item => item.id !== productId);
        this.save();
    }

    updateQuantity(productId, quantity) {
        const item = this.items.find(item => item.id === productId);
        if (item) {
            item.quantity = Math.max(1, quantity);
        }
        this.save();
    }

    clear() {
        this.items = [];
        this.save();
    }

    getTotal() {
        return this.items.reduce((total, item) => total + item.price * item.quantity, 0);
    }

    getCount() {
        return this.items.reduce((count, item) => count + item.quantity, 0);
    }

    save() {
        localStorage.setItem('cart', JSON.stringify(this.items));
        this.updateCartCount();
    }

    updateCartCount() {
        const countEl = document.getElementById('cartCount');
        if (countEl) {
            countEl.textContent = this.getCount();
        }
    }
}
"

Set-Content -Path "js/checkout.js" -Value "
const cart = new Cart();

function renderProducts() {
    const productsGrid = document.getElementById('productsGrid');
    if (!productsGrid) return;

    productsGrid.innerHTML = '';
    products.forEach(product => {
        const productCard = document.createElement('div');
        productCard.className = 'product-card';
        productCard.innerHTML = \`
            <img src='\${product.image}' alt='\${product.name}' class='product-card__image'>
            <div class='product-card__content'>
                <h3 class='product-card__name'>\${product.name}</h3>
                <p class='product-card__description'>\${product.description}</p>
                <div class='product-card__footer'>
                    <span class='product-card__price'>$\${product.price.toFixed(2)}</span>
                    <button class='btn btn--primary' data-id='\${product.id}'>Add to Cart</button>
                </div>
            </div>
        \`;
        productsGrid.appendChild(productCard);
    });
}

function renderCart() {
    const cartBody = document.getElementById('cartBody');
    const cartFooter = document.getElementById('cartFooter');
    if (!cartBody) return;

    if (cart.items.length === 0) {
        cartBody.innerHTML = '<p>Your cart is empty</p>';
        cartFooter.style.display = 'none';
    } else {
        cartBody.innerHTML = cart.items.map(item => \`
            <div class='cart-item'>
                <img src='\${item.image}' alt='\${item.name}' class='cart-item__image'>
                <div class='cart-item__details'>
                    <div class='cart-item__name'>\${item.name}</div>
                    <div class='cart-item__price'>$${item.price.toFixed(2)}</div>
                    <div class='cart-item__controls'>
                        <button class='cart-item__qty-btn' onclick='changeQuantity(\${item.id}, -1)'>-</button>
                        <span class='cart-item__qty'>\${item.quantity}</span>
                        <button class='cart-item__qty-btn' onclick='changeQuantity(\${item.id}, 1)'>+</button>
                        <button class='cart-item__remove' onclick='removeFromCart(\${item.id})'>Remove</button>
                    </div>
                </div>
            </div>
        \`).join('');
        document.getElementById('cartTotal').textContent = cart.getTotal().toFixed(2);
        cartFooter.style.display = 'block';
    }
}

function changeQuantity(productId, delta) {
    const item = cart.items.find(item => item.id === productId);
    if (item) {
        cart.updateQuantity(productId, item.quantity + delta);
        renderCart();
    }
}

function removeFromCart(productId) {
    cart.removeItem(productId);
    renderCart();
}

function showModal(id) {
    document.getElementById(id).classList.add('modal--show');
}

function hideModal(id) {
    document.getElementById(id).classList.remove('modal--show');
}

document.addEventListener('DOMContentLoaded', () => {
    renderProducts();

    // Add to cart buttons
    document.getElementById('productsGrid').addEventListener('click', (e) => {
        if (e.target.classList.contains('btn--primary') && e.target.dataset.id) {
            const productId = parseInt(e.target.dataset.id);
            const product = products.find(p => p.id === productId);
            if (product) {
                cart.addItem(product);
                renderCart();
                showModal('cartModal');
            }
        }
    });

    // Cart button
    document.getElementById('cartBtn').addEventListener('click', () => {
        renderCart();
        showModal('cartModal');
    });

    // Cart close
    document.getElementById('cartClose').addEventListener('click', () => {
        hideModal('cartModal');
    });

    // Checkout
    document.getElementById('checkoutBtn').addEventListener('click', () => {
        hideModal('cartModal');
        showModal('checkoutModal');
    });

    document.getElementById('checkoutClose').addEventListener('click', () => {
        hideModal('checkoutModal');
    });

    document.getElementById('backToCart').addEventListener('click', () => {
        hideModal('checkoutModal');
        showModal('cartModal');
    });

    // Complete checkout - simulated
    document.getElementById('completeCheckout').addEventListener('click', () => {
        const cardNumber = document.getElementById('cardNumber').value.replace(/\s/g, '');

        // Basic validation
        if (!document.getElementById('shipName').value || 
            !document.getElementById('shipEmail').value ||
            !document.getElementById('shipAddress').value ||
            !cardNumber) {
            alert('Please fill in all required fields');
            return;
        }

        if (cardNumber === '4242424242424242') {
            // Success
            hideModal('checkoutModal');
            document.getElementById('orderId').textContent = 'HD-' + Date.now();
            showModal('confirmationModal');
            cart.clear();
        } else if (cardNumber === '4000000000000002') {
            // Declined
            alert('Payment declined. Please try a different test card.');
        } else if (cardNumber.length === 16 && /^\d{16}$/.test(cardNumber)) {
            // For any other valid 16-digit test number, simulate success
            hideModal('checkoutModal');
            document.getElementById('orderId').textContent = 'HD-' + Date.now();
            showModal('confirmationModal');
            cart.clear();
        } else {
            alert('Please enter a valid 16-digit card number');
        }
    });

    // Continue shopping
    document.getElementById('continueShopping').addEventListener('click', () => {
        hideModal('confirmationModal');
    });

    // Close modals when clicking outside
    window.addEventListener('click', (e) => {
        if (e.target.classList.contains('modal')) {
            hideModal(e.target.id);
        }
    });
});
"

Set-Content -Path "css/style.css" -Value ":root {
    --color-primary: #1a5a6e;
    --color-secondary: #4a9fbf;
    --color-accent: #7fc5e0;
    --color-sand: #f2e5bc;
    --color-seafoam: #c9e6e6;
    --color-text: #1f2937;
    --color-text-light: #6b7280;
    --color-white: #ffffff;
    --color-border: #e5e7eb;
    --font-heading: 'Playfair Display', serif;
    --font-body: 'Inter', sans-serif;
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: var(--font-body);
    color: var(--color-text);
    line-height: 1.6;
    background-color: #fafbfc;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 1rem;
}

.header {
    background: var(--color-white);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: var(--shadow-sm);
}

.nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
}

.nav__logo {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.nav__logo-img {
    height: 40px;
    width: 40px;
}

.nav__logo-text {
    font-family: var(--font-heading);
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--color-primary);
}

.nav__cart-btn {
    position: relative;
    background: none;
    border: none;
    padding: 0.5rem;
    cursor: pointer;
    color: var(--color-text);
    transition: all 0.2s ease;
    border-radius: 0.5rem;
}

.nav__cart-btn:hover {
    background: var(--color-seafoam);
    color: var(--color-primary);
}

.nav__cart-count {
    position: absolute;
    top: -4px;
    right: -4px;
    background: var(--color-primary);
    color: var(--color-white);
    font-size: 0.75rem;
    padding: 0.125rem 0.375rem;
    border-radius: 9999px;
    min-width: 20px;
    text-align: center;
}

.hero {
    background: linear-gradient(135deg, var(--color-secondary) 0%, var(--color-primary) 100%);
    color: var(--color-white);
    padding: 4rem 1rem;
    text-align: center;
}

.hero__title {
    font-family: var(--font-heading);
    font-size: clamp(2rem, 5vw, 3.5rem);
    font-weight: 600;
    margin-bottom: 1rem;
}

.hero__subtitle {
    font-size: clamp(1rem, 2vw, 1.25rem);
    opacity: 0.95;
}

.products {
    padding: 3rem 1rem;
}

.products__title {
    font-family: var(--font-heading);
    font-size: clamp(1.75rem, 3vw, 2.25rem);
    text-align: center;
    margin-bottom: 2.5rem;
    color: var(--color-primary);
}

.products__grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 2rem;
}

.product-card {
    background: var(--color-white);
    border-radius: 0.75rem;
    overflow: hidden;
    box-shadow: var(--shadow-md);
    transition: all 0.3s ease;
}

.product-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}

.product-card__image {
    width: 100%;
    height: 280px;
    object-fit: cover;
}

.product-card__content {
    padding: 1.5rem;
}

.product-card__name {
    font-family: var(--font-heading);
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
    color: var(--color-primary);
}

.product-card__description {
    font-size: 0.875rem;
    color: var(--color-text-light);
    margin-bottom: 1rem;
    line-height: 1.5;
}

.product-card__footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.product-card__price {
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--color-primary);
}

.btn {
    padding: 0.625rem 1.25rem;
    border-radius: 0.5rem;
    border: none;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
}

.btn--primary {
    background: var(--color-primary);
    color: var(--color-white);
}

.btn--primary:hover {
    background: #154a5a;
}

.btn--secondary {
    background: var(--color-border);
    color: var(--color-text);
}

.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    z-index: 1000;
    overflow-y: auto;
}

.modal--show {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}

.modal__content {
    background: var(--color-white);
    border-radius: 0.75rem;
    width: 100%;
    max-width: 500px;
    max-height: 90vh;
    overflow-y: auto;
    box-shadow: var(--shadow-lg);
}

.modal__content--confirmation {
    text-align: center;
}

.modal__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem;
    border-bottom: 1px solid var(--color-border);
}

.modal__title {
    font-family: var(--font-heading);
    font-size: 1.5rem;
    color: var(--color-primary);
}

.modal__close {
    background: none;
    border: none;
    font-size: 2rem;
    cursor: pointer;
    color: var(--color-text-light);
    line-height: 1;
}

.modal__body {
    padding: 1.5rem;
}

.modal__footer {
    padding: 1.5rem;
    border-top: 1px solid var(--color-border);
}

.cart-item {
    display: flex;
    gap: 1rem;
    padding: 1rem 0;
    border-bottom: 1px solid var(--color-border);
}

.cart-item:last-child {
    border-bottom: none;
}

.cart-item__image {
    width: 80px;
    height: 80px;
    object-fit: cover;
    border-radius: 0.5rem;
}

.cart-item__details {
    flex: 1;
}

.cart-item__name {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.cart-item__price {
    color: var(--color-primary);
    font-weight: 500;
}

.cart-item__controls {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.cart-item__qty {
    width: 40px;
    text-align: center;
}

.cart-item__remove {
    color: #ef4444;
    background: none;
    border: none;
    cursor: pointer;
    font-size: 0.875rem;
}

.modal__total {
    font-size: 1.25rem;
    margin-bottom: 1rem;
}

.form__input {
    width: 100%;
    padding: 0.75rem;
    border: 1px solid var(--color-border);
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    font-size: 0.875rem;
}

.form__row {
    display: flex;
    gap: 1rem;
}

.form__input--half {
    width: 50%;
}

.payment__test-notice {
    background: #fef3c7;
    border: 1px solid #f59e0b;
    padding: 1rem;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    font-size: 0.875rem;
}

.checkout__actions {
    display: flex;
    gap: 1rem;
    margin-top: 1.5rem;
}

.checkout__actions .btn {
    flex: 1;
}

.footer {
    background: var(--color-text);
    color: var(--color-white);
    padding: 2rem 1rem;
    margin-top: 3rem;
}

.footer .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
}

.footer__text {
    opacity: 0.8;
}

.footer__links {
    display: flex;
    gap: 1.5rem;
}

.footer__link {
    color: var(--color-white);
    text-decoration: none;
    opacity: 0.8;
    transition: opacity 0.2s ease;
}

.footer__link:hover {
    opacity: 1;
}

@media (max-width: 768px) {
    .products__grid {
        grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
        gap: 1.5rem;
    }

    .hero {
        padding: 2.5rem 1rem;
    }
}
