Set-Content -Path "js/cart.js" -Value "class Cart {
    constructor() {
        this.items = JSON.parse(localStorage.getItem('cart')) || [];
        this.updateCartCount();
    }

    addItem(product, quantity = 1) {
        const existingItem = this.items.find(item => item.id === product.id);
        if (existingItem) {
            existingItem.quantity += quantity;
        } else {
            this.items.push({ ...product, quantity });
        }
        this.save();
    }

    removeItem(productId) {
        this.items = this.items.filter(item => item.id !== productId);
        this.save();
    }

    updateQuantity(productId, quantity) {
        const item = this.items.find(item => item.id === productId);
        if (item) {
            item.quantity = Math.max(1, quantity);
        }
        this.save();
    }

    clear() {
        this.items = [];
        this.save();
    }

    getTotal() {
        return this.items.reduce((total, item) => total + item.price * item.quantity, 0);
    }

    getCount() {
        return this.items.reduce((count, item) => count + item.quantity, 0);
    }

    save() {
        localStorage.setItem('cart', JSON.stringify(this.items));
        this.updateCartCount();
    }

    updateCartCount() {
        const countEl = document.getElementById('cartCount');
        if (countEl) {
            countEl.textContent = this.getCount();
        }
    }
}
"

Set-Content -Path "js/checkout.js" -Value "
const cart = new Cart();

function renderProducts() {
    const productsGrid = document.getElementById('productsGrid');
    if (!productsGrid) return;

    productsGrid.innerHTML = '';
    products.forEach(product => {
        const productCard = document.createElement('div');
        productCard.className = 'product-card';
        productCard.innerHTML = \`
            <img src='\${product.image}' alt='\${product.name}' class='product-card__image'>
            <div class='product-card__content'>
                <h3 class='product-card__name'>\${product.name}</h3>
                <p class='product-card__description'>\${product.description}</p>
                <div class='product-card__footer'>
                    <span class='product-card__price'>$\${product.price.toFixed(2)}</span>
                    <button class='btn btn--primary' data-id='\${product.id}'>Add to Cart</button>
                </div>
            </div>
        \`;
        productsGrid.appendChild(productCard);
    });
}

function renderCart() {
    const cartBody = document.getElementById('cartBody');
    const cartFooter = document.getElementById('cartFooter');
    if (!cartBody) return;

    if (cart.items.length === 0) {
        cartBody.innerHTML = '<p>Your cart is empty</p>';
        cartFooter.style.display = 'none';
    } else {
        cartBody.innerHTML = cart.items.map(item => \`
            <div class='cart-item'>
                <img src='\${item.image}' alt='\${item.name}' class='cart-item__image'>
                <div class='cart-item__details'>
                    <div class='cart-item__name'>\${item.name}</div>
                    <div class='cart-item__price'>$${item.price.toFixed(2)}</div>
                    <div class='cart-item__controls'>
                        <button class='cart-item__qty-btn' onclick='changeQuantity(\${item.id}, -1)'>-</button>
                        <span class='cart-item__qty'>\${item.quantity}</span>
                        <button class='cart-item__qty-btn' onclick='changeQuantity(\${item.id}, 1)'>+</button>
                        <button class='cart-item__remove' onclick='removeFromCart(\${item.id})'>Remove</button>
                    </div>
                </div>
            </div>
        \`).join('');
        document.getElementById('cartTotal').textContent = cart.getTotal().toFixed(2);
        cartFooter.style.display = 'block';
    }
}

function changeQuantity(productId, delta) {
    const item = cart.items.find(item => item.id === productId);
    if (item) {
        cart.updateQuantity(productId, item.quantity + delta);
        renderCart();
    }
}

function removeFromCart(productId) {
    cart.removeItem(productId);
    renderCart();
}

function showModal(id) {
    document.getElementById(id).classList.add('modal--show');
}

function hideModal(id) {
    document.getElementById(id).classList.remove('modal--show');
}

document.addEventListener('DOMContentLoaded', () => {
    renderProducts();

    // Add to cart buttons
    document.getElementById('productsGrid').addEventListener('click', (e) => {
        if (e.target.classList.contains('btn--primary') && e.target.dataset.id) {
            const productId = parseInt(e.target.dataset.id);
            const product = products.find(p => p.id === productId);
            if (product) {
                cart.addItem(product);
                renderCart();
                showModal('cartModal');
            }
        }
    });

    // Cart button
    document.getElementById('cartBtn').addEventListener('click', () => {
        renderCart();
        showModal('cartModal');
    });

    // Cart close
    document.getElementById('cartClose').addEventListener('click', () => {
        hideModal('cartModal');
    });

    // Checkout
    document.getElementById('checkoutBtn').addEventListener('click', () => {
        hideModal('cartModal');
        showModal('checkoutModal');
    });

    document.getElementById('checkoutClose').addEventListener('click', () => {
        hideModal('checkoutModal');
    });

    document.getElementById('backToCart').addEventListener('click', () => {
        hideModal('checkoutModal');
        showModal('cartModal');
    });

    // Complete checkout - simulated
    document.getElementById('completeCheckout').addEventListener('click', () => {
        const cardNumber = document.getElementById('cardNumber').value.replace(/\s/g, '');

        // Basic validation
        if (!document.getElementById('shipName').value || 
            !document.getElementById('shipEmail').value ||
            !document.getElementById('shipAddress').value ||
            !cardNumber) {
            alert('Please fill in all required fields');
            return;
        }

        if (cardNumber === '4242424242424242') {
            // Success
            hideModal('checkoutModal');
            document.getElementById('orderId').textContent = 'HD-' + Date.now();
            showModal('confirmationModal');
            cart.clear();
        } else if (cardNumber === '4000000000000002') {
            // Declined
            alert('Payment declined. Please try a different test card.');
        } else if (cardNumber.length === 16 && /^\d{16}$/.test(cardNumber)) {
            // For any other valid 16-digit test number, simulate success
            hideModal('checkoutModal');
            document.getElementById('orderId').textContent = 'HD-' + Date.now();
            showModal('confirmationModal');
            cart.clear();
        } else {
            alert('Please enter a valid 16-digit card number');
        }
    });

    // Continue shopping
    document.getElementById('continueShopping').addEventListener('click', () => {
        hideModal('confirmationModal');
    });

    // Close modals when clicking outside
    window.addEventListener('click', (e) => {
        if (e.target.classList.contains('modal')) {
            hideModal(e.target.id);
        }
    });
});
"

