    font-size: 1.5rem;
    font-weight: 600;
    color: var(--color-primary);
}

.nav__cart-btn {
    position: relative;
    background: none;
    border: none;
    padding: 0.5rem;
    cursor: pointer;
    color: var(--color-text);
    transition: all 0.2s ease;
    border-radius: 0.5rem;
}

.nav__cart-btn:hover {
    background: var(--color-seafoam);
    color: var(--color-primary);
}

.nav__cart-count {
    position: absolute;
    top: -4px;
    right: -4px;
    background: var(--color-primary);
    color: var(--color-white);
    font-size: 0.75rem;
    padding: 0.125rem 0.375rem;
    border-radius: 9999px;
    min-width: 20px;
    text-align: center;
}

.hero {
