.product-card__description {
    font-size: 0.875rem;
    color: var(--color-text-light);
    margin-bottom: 1rem;
    line-height: 1.5;
}

.product-card__footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.product-card__price {
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--color-primary);
}

.btn {
    padding: 0.625rem 1.25rem;
    border-radius: 0.5rem;
