.modal__total {
    font-size: 1.25rem;
    margin-bottom: 1rem;
}

.form__input {
    width: 100%;
    padding: 0.75rem;
    border: 1px solid var(--color-border);
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    font-size: 0.875rem;
}

.form__row {
    display: flex;
    gap: 1rem;
}

.form__input--half {
    width: 50%;
}

.payment__test-notice {
    background: #fef3c7;
    border: 1px solid #f59e0b;
    padding: 1rem;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    font-size: 0.875rem;
